const rows=$input.all().map(i=>i.json);
if(!rows.length||!rows[0].snapshot_json) throw new Error('No validated snapshot; import one first');
const row=rows[0],s=JSON.parse(row.snapshot_json);
const group=players=>players.reduce((a,p)=>{for(const pos of p.positions)(a[pos]??=[]).push(p);return a},{});
const counts=s.roster.reduce((a,p)=>{a[p.slot]=(a[p.slot]||0)+1;return a},{});
const gaps=Object.entries(s.league_settings.roster_slots).filter(([slot])=>!['BN','IR','IR+'].includes(slot)).map(([slot,required])=>({slot,required,assigned:counts[slot]||0,unfilled:Math.max(0,required-(counts[slot]||0))}));
return [{json:{schema_version:1,generated_at:new Date().toISOString(),snapshot_row_id:row.id,league_id:s.league_id,season:s.season,current_week:s.current_week,captured_at:s.captured_at,is_sample:s.is_sample,platform:s.platform,league_settings:s.league_settings,players:s.roster,players_by_position:group(s.roster),matchups:s.roster.map(p=>({name:p.name,team:p.team,opponent:p.opponent??null,source:'manual snapshot; unverified'})),roster_needs:{slot_gaps:gaps,bye_players:s.roster.filter(p=>p.opponent==='BYE'),note:'Slot gaps describe supplied lineup assignments; no performance ranking inferred.'},waiver_candidates:s.waiver_players,waivers_by_position:group(s.waiver_players),research_required:['Verify player identities, current NFL teams, and Yahoo eligibility','Verify actual Yahoo scoring and roster settings','Fetch sourced current matchups, injuries, usage and statistics before recommendations'],provenance:{source:'manual JSON',identity_verified:false,statistics_fetched:false,injuries_fetched:false},constraints:{advisory_only:true,automatic_transactions:false,paid_ai_apis:false},warnings:[...(s.is_sample?['SAMPLE DATA — never use for actual recommendations']:[]),...(!s.league_settings.verified?['League settings unverified; full PPR is provisional']:[]),'Latest means most recently imported snapshot. Player names are structurally validated, not checked against a live player registry.']}}];
